style.css:
@-moz-document domain("pinterest.com") {
/* 1. Set your custom forest image as the background */
    body, 
    #initial-focus-wrapper, 
    div[data-test-id="main-container"] {
        background-image: url('https://imgur.com') !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* 2. Make the main pin feed panels fully transparent to maximize background visibility */
    div[role="main"],
    .Grid,
    div[data-test-id="board-header"],
    div[data-test-id="pin"],
    div[data-test-id="pin-save-dropdown"] {
        background-color: rgba(255, 255, 255, 0.15) !important; /* Extremely clear glass panels */
        backdrop-filter: blur(2px) !important; /* Low blur keeps the forest sharp */
        border: none !important;
    }

    /* 3. Deep Black Top Search Bar & Header */
    header[role="banner"],
    header[role="banner"] > div,
    div[data-test-id="search-box-input"],
    form[name="search"] input {
        background-color: #0b0b0b !important; /* Solid deep black */
        color: #ffffff !important; /* Keeps typed search text white for visibility inside the bar */
        border: none !important;
    }

    /* 4. Deep Black Side Panels & Navigation Menus */
    div[role="navigation"],
    div[data-test-id="sidebar"],
    div[role="menu"],
    div[data-test-id="search-flyout"],
    #guided-help-container,
    div[role="dialog"] {
        background-color: #0b0b0b !important; /* Solid deep black for side elements and dropdowns */
        border-radius: 12px !important;
        border: 1px solid #222222 !important;
    }

    /* 5. Force ALL main page text and words to be Pure Black */
    h1, h2, h3, p, span, div, a, .tread-muted, div[color="subtle"] {
        color: #000000 !important; /* Pure black text */
        text-shadow: 1px 1px 2px rgba(255, 255, 255, 0.6) !important; /* Light glow ensures readability over dark trees */
    }

    /* 6. Fix Search Bar Placeholder text */
    form[name="search"] input::placeholder {
        color: #888888 !important;
    }

    /* 7. Adjust header navigation icons to pop against black */
    header[role="banner"] svg {
        color: #ffffff !important; /* Header navigation icons stay bright */
    }
}
